head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL30000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30000.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_yearAu_onclick
 * @description btn_yearAu 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_yearAu_onclick = function(e){
    try {
        scwin.yearAu()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30000.btn_yearAu_onclick' }); }
};

/**
 * @method
 * @name btn_listPrint_onclick
 * @description btn_listPrint 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_listPrint_onclick = function(e){
    try {
        scwin.listPrint()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30000.btn_listPrint_onclick' }); }
};

/**
 * @method
 * @name btn_listNoPrint_onclick
 * @description btn_listNoPrint 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_listNoPrint_onclick = function(e){
    try {
        scwin.listNoPrint()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30000.btn_listNoPrint_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name yearAu
 * @description year Au 처리
 * @returns {void}
 * @hidden N
 */
scwin.yearAu = function () {
    document.$c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDFIL30100.xml');
};

/**
 * @method
 * @name listPrint
 * @description list Print 처리
 * @returns {void}
 * @hidden N
 */
scwin.listPrint = function () {
    document.$c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDFIL30201.xml');
};

/**
 * @method
 * @name listNoPrint
 * @description list No Print 처리
 * @returns {void}
 * @hidden N
 */
scwin.listNoPrint = function () {
    document.$c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDFIL30301.xml');
};

/**
 * @method
 * @name viewManualKeyWord
 * @description view Manual Key Word 처리
 * @param {String} submitManualClssId submitManualClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewManualKeyWord = async function (submitManualClssId) {
    const viewManulURL = '/ui/jsp/JLDFIL35400.xml';
    await $c.win.openPopup(viewManulURL, { id: "manualWin", scrollbars: true, resizable: false, width: "1000", height: "650", type: "pageFramePopup" }, { method: "searchSubmitManual", submitManualClssId: submitManualClssId });
};
